exec((__import__('pathlib').Path(__file__).parent/'ghost_a.py').read_text(encoding='utf-8').split("B('不祥之兆'")[0])
B('寻人',[
C('li_grandmother','李三根的外祖母','她最初只以寻人启事中的家属和电话里响亮的老妇人声音出现。十八岁的外孙李三根失踪，启事悬出二十万元，使三个准备行骗的青年以为找到了容易下手的老人。电话中，她反复呼唤三根，声音带哭，说明那些钱是自己一生积蓄；她也说身边没有别人，若不是外孙心智有限，他也未必肯陪自己。听到对方虚构已经找到外孙，她答应独自带钱赴约，行动缓慢地走上旧楼。纸袋被抢后，她才指出三个青年每人见面都先抢袋子，而且知道他们所谓找到外孙完全是谎话。随后她张开血红大口，最后一个青年眼前一黑；次晨三名青年均被发现大量失血，袋中只有冥纸。她的身份由求助老人转为惩罚骗子的食人异类，但原文没有给她生前死因、法术体系或真正寻回外孙的结局。终局的她仍围绕失踪亲人和对恶意欺骗的愤怒行动，不能把所有陌生人都当成猎物，也不能把她的近身吞噬表现夸大成远程吸尽城市血液的能力。','三名骗徒死亡，纸袋变为冥纸；外孙下落仍未知。','佝偻、行动迟缓、声音极响的老妇人；袭击时张开血红大口。','寻找外孙，惩罚借寻亲敲诈她的人。','表面耐心接受安排，识破后用嘲讽揭穿并近身袭击。','可显成人形并乘车、上楼；近身张口袭击后目标出现七窍失血，机制未解释。',[(15,21,'寻亲诉求与被骗赴约'),(35,41,'识破、张口袭击与死亡结果')],[('有人声称掌握亲人下落','说法具体但尚未核实','要求见人并亲自赴约。'),('对方先抢酬金','证明只在意财物且谎话暴露','冷冷指出重复手法，逼其面对后果。'),('无辜者请求协助','没有骗抢行为证据','围绕真实信息交谈，不自动发动惩罚。')],roles=['主角','反派'],ghost=True,scores={'physical':2,'energy':3,'scope':1,'sustain':2,'range':1,'combat':3},tier='并',baseline={'destruction':'已造成单个人体致命失血；没有建筑破坏证据。','durability':'未遭有效攻击，灵体抗性未明。','energy':'吞噬或失血机制异常，限已展示的近身事件。'},uncertainties=['李三根是否真是她的外孙及悬赏身份没有独立核实。','前两名青年遇害过程在视角外。']),
C('search_leader','寻人骗局的老大','他是三个结拜青年中的老大，平日随身藏刀，夜里寻找可掠夺的目标。被风吹来的报纸上二十万元悬红吸引后，三人先考虑是否能冒充失踪者；发现无人相像，又改为假称寻获李三根。他不是每句话都由自己出面的人，知道老二口齿最利落，便让对方打电话；关键时刻由他决定报出天台木屋的真实住址，因为一旦拿到钱就可以搬走。他和老二商量，老人容易骗便软取，不肯交钱便抢劫绑人，说明他从开始就把暴力当作后备办法。等待时他也怀疑老人深夜独携巨款是否合理，却没有让疑点压过贪欲。楼梯声久久不近，他先遣老二下楼，最后亲自扶老人上来，又压住她的嘴避免惊动邻居。纸袋到手，他只顾看钞票，直到老人揭穿谎话、张开怪口，才发现已经无法逃开。这个终局版本是死于自己主动建立的骗局，而非具备天才策划能力的大盗；他有分工和风险计算，却会把弱者外表误当成绝对可控制。','被老妇人近身袭击，次晨以七窍失血尸体被发现。','二十出头、目光游移的青年；衣着未详写。','快速获得悬赏钱财，保持小团伙主导权。','先计算和派人试探，临近得手时容易忽略异常。','小团伙分工、欺诈安排及准备抢劫；藏刀未展示实际刺杀。',[(7,23,'结伙、分工及软硬两套方案'),(31,41,'等待、抢钱与死亡')],[('看见高额悬赏','认为受害人焦急好骗','先找低成本试探途径。'),('同伙遇到不明状况','收益仍在眼前','派另一人查看，自己暂留后方。'),('财物已经到手','异常被贪欲盖过','急于控制现场而延误撤离。')],roles=['反派'],revive=True,scores={'physical':1,'energy':0,'scope':1,'sustain':1,'range':1,'combat':2},tier='并'),
C('search_talker','寻人骗局的老二','老二被同伙认为最伶牙俐齿，因此承担寻人骗局中的电话交涉。他先踢电话亭、喝退正在用电话的少女，利用凶相取得便利，再换成懂事和照料老人的语气，编造外孙已被找到、洗过澡并安睡的整套说法。听见老妇人焦急而孤独的反应，他没有同情，反而更确信可以从她身上取得全部积蓄。他原先想把假称找到的人送上门，转念又担心对方家里有帮手，便临时改口，让她独自带钱到三人的住处；这表明他能根据风险及时调整话术，但调整目的始终是孤立目标。回屋后他同老大准备必要时抢劫绑人，还以外孙可能是老人全部寄托来解释深夜赴约的反常。楼梯声迟迟未到，他又显得急躁，被老大派下楼查看，随后在视角之外失去消息。次日他的尸体与另两人一起被发现。终局的老二可保留擅长说话、观察弱点和急于兑现利益的习惯，却没有证据支持催眠、读心或无懈可击的伪装；面对掌握事实的听者，他的话术一样会被看穿。','下楼查看后遇害，次晨被发现大量失血死亡。','年轻男子，神情游移；以忽凶忽软的语气见长。','利用别人寻亲的焦急获利。','迅速编造解释，发现等待过长便焦躁。','电话诈骗与根据听者反应改口；没有精神控制。',[(13,21,'驱赶少女、虚构照料与孤立目标'),(25,41,'替异常找理由及死亡')],[('受害者透露焦急','信息可被拿来编造可信细节','顺着对方最想听的话保证。'),('交易地点有未知帮手','担心被识破或控制','设法让对方独自赴约。'),('计划进度异常','同伙仍催促推进','用临时解释自我安慰，也可能冒险探查。')],roles=['反派'],revive=True,scores={'physical':1,'energy':0,'scope':1,'sustain':1,'range':1,'combat':1},tier='纸'),
C('search_lookout','寻人骗局的老三','老三与另外两个年轻人结拜，组成在夜间游荡、准备持刀掠夺的小团伙。他看到悬赏后没有主张放弃，而提醒同伙失踪者家属必定着急，既然并非每次都能遇到值二十万元的线索，就应随机应变去捞一笔。这个建议把报纸上的寻人从偶然消息变成了可利用的机会。他没有主导电话欺骗，却接受大家已经形成的分工；三人回到天台木屋以后，不必细谈，他便拿着啤酒下楼，到街口等老妇人。这种默契说明他熟悉团伙的协同行动，但不意味着经过专业训练。看见老人从出租车上吃力下来，他暂时像热心人一样扶她，随即伸手想接装钱的纸袋；老人紧握不放，他的心思仍只在钱上。他陪老人上楼后没有再出现在老大的视野里，最终也被发现死于大量失血。终局的老三是以殷勤外表接近目标的执行者，他对亲属焦急的理解用来剥削别人，不能因一时扶人便被改写成误入歧途的无辜者；也不能凭藏刀和结拜身份赋予他高超格斗能力。','接老妇人上楼后遇害，次晨尸体被发现。','二十出头的青年，能装出主动扶助老人的样子。','跟随团伙从容易操纵的目标身上获利。','伪装热心，接近目标后先试探财物。','街口接应、伪装帮助与近身接近；未展示正式战斗技巧。',[(11,23,'参与决策与默契接应'),(27,41,'接人、试拿钱袋与死亡')],[('同伙犹豫是否行骗','损失看似很小而收益大','推动试探，强调随机应变。'),('目标行动迟缓','需要帮助才能进入圈套','主动搀扶并套近乎。'),('财物近在手边','对方尚未警觉','先试探能否接过或拿走。')],roles=['反派'],revive=True,scores={'physical':1,'energy':0,'scope':1,'sustain':1,'range':1,'combat':1},tier='纸')],excluded=[{'name':'李三根','reason':'寻人对象只在启事及对话中提及，未实际参与本篇行动。'}])
B('房客',[
C('landlord_husband','怪房客的男房东','他与妻子都有工作，为分担房屋分期付款，决定把新居里的一间空房出租。他们把住所视作共同心血，对房客列出许多严格条件，终于遇到谈吐文雅、强调安静的王先生，最初喜不自胜。王先生按月付租，几乎不露面，正合他们当初的要求；但几个月过去，同住一屋仍见不到人，便利逐渐变成难以忍受的未知。他先试着邀请房客吃饭，被冷淡拒绝，再趁确定无人时拿备用钥匙探看，却发现锁已换过。这些举动既是好奇，也越过了自己原先答应的独立生活边界。后来他抱着小说整夜等候，仍未等到，疲倦和疑虑引起婚后第一次激烈争吵。妻子提出落横闩迫使房客按铃，办法一样没有成功；两人最终听到入门声追去敲门，却被房内的寂静吓得退开。故事没有证明王先生是鬼，更没有揭出犯罪。他的终局是仍与无法确认的房客共居、因无法见到而不安。演绎时他会想寻根究底，但应区分真正危险与对别人隐私的焦虑，不能把疑心当成侦探的确定结论。','仍未查明王先生身份，两人停止敲门；房客按时付租而未被证实作恶。','普通已婚上班族；用吸烟、守夜和贴耳听门表现焦虑。','守住共同居所的安全感，弄清身边人的真实存在。','从礼貌邀请升级到试钥匙、守夜和敲门。','日常观察和安排碰面；调查行动受房客隐私、门锁与自身胆量限制。',[(13,41,'出租、满意转疑虑与试钥匙'),(49,67,'守夜、争吵、最后退却')],[('共同住所出现反常作息','正常接触长期落空','先问候和约见，再核对生活痕迹。'),('求证被一再回避','疑虑影响伴侣','会变急躁，可能越界，随后承担争吵后果。'),('面对无回应的封闭空间','没有实际危险证据','恐惧可能压过好奇，选择退开。')]),
C('landlord_wife','怪房客的女房东','她与丈夫一起用工作收入购买居住单位，房贷让他们选择出租空房，却仍希望家中保持安静、清洁与两个人的亲密生活。王先生看房时主动说明孤僻、不喜打扰，她与丈夫立即认定找到了理想房客。房租每月准时放在桌上，房客却仿佛从屋内消失，久而久之，睡前询问是否见到他成了夫妻共同的仪式。她并不是单纯随丈夫惊慌的人：当整夜守候失败、丈夫的执着引起争吵以后，是她提出把铁门横闩落下，使只有钥匙的王先生也必须按铃。这是针对现有门锁条件设计的实际办法，仍没有得到预期的会面。两人越向别人诉说，越把怪异当成威胁，最后听到开门声一同冲出去敲房门，却又被沉默吓退。故事停在无法确定的边界上，既没有确认鬼魂，也没有证实房客违约。综合终局的她保留精打细算、保护生活和有具体主意的一面，也带着夫妻相互放大恐惧的经验。她能提出核验方法，但不能因失败就知道门后是什么；在别的世界，她仍需以可观察事实评估不安。','与丈夫一同退离房门，未查明房客身份。','普通年轻妻子；具体服饰与容貌未详写。','保持家庭安宁，找到能解除夫妻共同疑虑的办法。','先商量、埋怨，再想出具体的接触安排。','以门闩和作息设计碰面条件，属于日常应变。',[(13,29,'共同购房出租与最初满意'),(53,67,'争吵、横闩办法和退却')],[('家庭财务有压力','存在闲置资源','倾向严格设条件后利用资源。'),('反复等待没有结果','单靠猜想正在伤害关系','提出改变条件的实际测试。'),('伴侣同样恐惧','双方都没有掌握证据','靠近彼此并退到安全处，不独自断言真相。')])],excluded=[{'name':'王先生','reason':'本篇核心谜面与一次性配角，按约付租；没有证明主动对抗或超常身份。'}],notes=['保留悬疑，不把房客自动定为鬼或反派。'])
B('择时剖腹',[
C('doctor_ding','丁医生（择时剖腹）','丁医生是城中手术口碑很好的妇科与外科医生，值夜班前习惯在心里预演手术程序，以免临场失措。这晚有一台切除手术和一台择定时辰的剖腹生产，富豪家庭希望孩子在精确的吉时出生，他觉得这种把古老命理和现代手术结合的做法荒谬，却仍按专业职责准备。走向医院时，他无意识跟随前面穿病服的人，看到对方惨灰脸色，先想到健康问题，又被强烈敌意逼退。陌生人随后突然改成亲切感激的笑容，并在尽头墙前消失，他倾向用越过灌木等常理解释，没敢继续查证。进入手术室后过程顺利，孩子也在约定时刻出生；但他一瞬间在男婴脸上看见那陌生人的仇恨神情，惊得松手，幸得护士接住。事后有人议论，他只干笑，仍无法确定是否眼花。终局中的他既有真实的外科经验，也有专业自信被未知击穿的记忆。手术技巧不能当作战斗疗愈术，陌生人是否转生也不是他确诊的事实；面对类似异常，他更需要同事协助和记录，而不是孤自承担所有判断。','完成剖腹生产，曾因异常面容松手，婴儿被护士接住；未发生已写出的后续伤亡。','成熟医生，外观未详；习惯礼貌点头，事后以干笑回避解释。','完成医疗职责，维持对专业判断的信任。','先用合理解释安定自己，强烈异常可打断动作。','熟练妇科外科手术与术前流程推演；需要医院设备和团队。',[(7,29,'职业、手术规划和择时安排'),(31,53,'陌生人异常'),(63,79,'分娩与失手')],[('任务时间被非专业要求限定','仍可安全安排','先完成专业准备，再处理对方期待。'),('病人出现反常面容或举动','尚无医学解释','观察并寻求同事复核，避免独断。'),('自己动作失误','有人能接替','立即让团队保护患者，不能靠威望否认事实。')],ability_name='临床手术与程序预演',uncertainties=['陌生病人与婴儿是否同一人格未获证实。'])],excluded=[{'name':'灰脸病人／新生儿','reason':'被丁医生联系的异常形象，未证明同一人格或主动加害；不把诡异表情当反派行为。'}])
B('搭电梯',[
C('elevator_wang','小王（搭电梯）','小王大学读到一半便工作，收入虽不高，仍把自己打扮得英俊潇洒，口齿也伶俐。他习惯在短暂的电梯同行中对陌生女性产生浪漫乃至越界的幻想，却知道现实中的身体接触会带来后果，通常只在心里想。一次赶电梯，他呼喊等候，一位年轻女子替他按开门，他马上微笑道谢，并因满厢女乘客而得意。冷淡的眼光没有令他退缩，反而被他解释为潜在的兴趣；他引用呼吸和狭小空间的话题，希望显得有知识，又把假设快要窒息的问题变成搭话机会。期待的惊呼没有出现，背后却有人告诉他，需要呼吸的只有他一个。此时他才注意到电梯没有任何楼层灯亮起，伸手要按自己的楼层，又被右边那只冰冷的手挡住。故事在他认定满厢都是鬼的瞬间结束，未写他是否获救或遇害。终局的小王因此不是已经通晓阴阳通勤的人，而是被自己的遐想遮住关键观察、终于受到惊吓的普通青年。他会说话、会讨好，也会误读礼貌，不拥有让异性服从的魅力权能。','认定同梯女性皆为鬼，结局停在按钮被挡住的瞬间。','年轻、英俊高大，刻意打扮潇洒；得意时微笑，尴尬时脸红。','在日常生活中寻求被异性注意的新鲜感。','先展示谈吐；发现真实危险时原有自信会崩塌。','口齿与社交试探；并无科学专家或战斗能力证明。',[(3,19,'背景、幻想与搭梯'),(21,35,'搭话、异常与受阻')],[('获得陌生人的小帮助','对方外貌使他心动','道谢并尝试延长交流。'),('对方反应冷淡','自己仍期待关注','可能把冷淡误解成含蓄，需要现实反馈纠正。'),('生活细节违背常识','诸如控制板无目的地','从幻想转入观察，尝试恢复正常操作。')]),
C('elevator_women','无须呼吸的电梯女乘客','这群年轻女子出现在小王每日熟悉的办公楼电梯中，外观与城市中冷淡的上班族没有显著区别。她们中有人按住开门按钮，让赶来的小王进入；有人回望他，或以不屑神情回应他自得的微笑。叙事没有逐一给出姓名和独立经历，因此只把她们作为在同一空间中表现相近的群体记录。小王用人类呼吸量和密闭空间的假设进行搭话时，她们没有顺着他的期待惊叫，而由其中一人平静指出只有他需要空气。随后楼层按钮全无亮光，小王想按第二十五层，又被替他开过门的女子挡住，接触感冰冷。这个动作使群体从神秘同行者成为阻止正常离开的阶段性对立者，但原文到此即止，没有写她们杀人、吸气或把电梯带到阴间。她们的可用形态只有看似正常的女性显现、交谈和近身阻挡；不需要呼吸是自己的陈述，未接受进一步测试。演绎可以保留平静、疏离与对冒失搭话的反感，不能凭群体鬼魂身份添加无限穿墙、群体魅惑或必死结界。','仍与小王同处电梯，阻止其按楼层；后续去向和目的未交代。','约二十二至三十岁的女性群体，外表清秀冷淡；触碰到的手冰冷。','未明确交代；目前共同维持不按正常楼层运行的同行状态。','以沉默、简短纠正和挡手回应小王。','人形显现、交谈和近身阻挡；自称不需呼吸。',[(15,23,'开门与群体外观'),(29,35,'不需呼吸的宣言与阻止按钮')],[('活人自顾自搭话','把自己的需要当成所有人的需要','冷淡纠正其前提。'),('有人擅自改变行进选择','与她们当前意图冲突','由近旁成员伸手阻止。'),('被追问目的','原作没有已知答案','允许沉默和有限回应，不编造阴间组织规则。')],roles=['阶段性对立者'],ghost=True,scores={'physical':1,'energy':1,'scope':1,'sustain':1,'range':0,'combat':1},tier='纸',baseline={'durability':'未遭攻击；不需呼吸不等于免疫物理伤害。','stamina':'自称不需呼吸，其他维持条件未知。'},uncertainties=['人数文本表述有七八人与十人等不一致，不固定编制。','目的与是否加害均未明。'])])
